{"implementation":"import math


def _finite_number(value, field):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(field + " must be a finite number")
    number = float(value)
    if not math.isfinite(number):
        raise ValueError(field + " must be a finite number")
    return number


def api_call_loss_filter(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "threshold" not in case or "calls" not in case:
        raise ValueError("case must contain threshold and calls")

    threshold = _finite_number(case["threshold"], "threshold")
    if threshold < 0:
        raise ValueError("threshold must be nonnegative")

    calls = case["calls"]
    if not isinstance(calls, list):
        raise ValueError("calls must be a list")

    validated = []
    seen_ids = set()
    required = (
        "call_id",
        "loss_without_call",
        "loss_with_call",
        "prediction_tokens",
        "parseable",
    )

    for position, call in enumerate(calls):
        if not isinstance(call, dict):
            raise ValueError("each call must be an object")
        for field in required:
            if field not in call:
                raise ValueError("call is missing required field: " + field)

        call_id = call["call_id"]
        if not isinstance(call_id, str) or not call_id:
            raise ValueError("call_id must be a nonempty string")
        if call_id in seen_ids:
            raise ValueError("call_id values must be unique")
        seen_ids.add(call_id)

        loss_without = _finite_number(
            call["loss_without_call"], "loss_without_call"
        )
        loss_with = _finite_number(call["loss_with_call"], "loss_with_call")
        if loss_without < 0 or loss_with < 0:
            raise ValueError("loss values must be nonnegative")

        prediction_tokens = call["prediction_tokens"]
        if isinstance(prediction_tokens, bool) or not isinstance(
            prediction_tokens, int
        ):
            raise ValueError("prediction_tokens must be an integer")
        if prediction_tokens < 0:
            raise ValueError("prediction_tokens must be nonnegative")

        parseable = call["parseable"]
        if not isinstance(parseable, bool):
            raise ValueError("parseable must be a boolean")

        validated.append(
            (
                position,
                call_id,
                loss_without,
                loss_with,
                prediction_tokens,
                parseable,
            )
        )

    diagnostics = []
    for _, call_id, loss_without, loss_with, prediction_tokens, parseable in validated:
        normalized_gain = (loss_without - loss_with) / max(1, prediction_tokens)
        accepted = parseable and normalized_gain >= threshold
        diagnostics.append(
            {
                "call_id": call_id,
                "normalized_gain": round(normalized_gain, 6),
                "accepted": accepted,
            }
        )

    accepted_call_ids = [
        diagnostic["call_id"] for diagnostic in diagnostics if diagnostic["accepted"]
    ]
    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics,
    }


def solve(case):
    return api_call_loss_filter(case)
